mapper.select:
SELECT T.ID, T.ACTION, T.PRIORITY, T.STATUS, T.PARK_ID, PARK.PARK_NAME, T.SOURCE_TYPE, T.SOURCE_ID, T.BADGE, STAFF.NAME, T.PERSON_ID, T.CARD_NO, T.CODE, T.REMARK, T.CONSUME, T.TIMES, T.OVER_TIME, T.CREATE_TIME, T.UPDATE_TIME, T.OPT_USER FROM SMT_ISC_CARD_TASK T LEFT JOIN SMT_STAFF STAFF ON T.SOURCE_ID = STAFF.ID LEFT JOIN SMT_PARK PARK ON T.PARK_ID = PARK.ID
AND T.PARK_ID IN
#{parkId}
AND T.PARK_ID = #{query.parkId}
AND T.BADGE LIKE CONCAT(CONCAT('%',#{query.badge}),'%')
AND STAFF.NAME LIKE CONCAT(CONCAT('%',#{query.name}),'%')
AND T.CARD_NO LIKE CONCAT(CONCAT('%',#{query.cardNo}),'%')
AND T.ACTION = #{query.action}
AND T.STATUS = #{query.status}
AND T.CODE = #{query.code}
AND T.CREATE_TIME >= TO_DATE(#{query.startTime,jdbcType=DATE}, 'yyyy-MM-dd')
AND T.CREATE_TIME < TO_DATE(#{query.endTime,jdbcType=DATE}, 'yyyy-MM-dd') + 1
ORDER BY T.CREATE_TIME DESC, T.ID DESC

SELECT PERSON_ID FROM (
	SELECT PERSON_ID
	FROM SMT_ISC_CARD_TASK
	WHERE BADGE = #{badge}
	  AND PARK_ID = #{parkId}
	  AND CARD_NO = #{cardNo}
	  AND STATUS = 1
	  AND PERSON_ID IS NOT NULL
	ORDER BY UPDATE_TIME DESC, ID DESC
) WHERE ROWNUM = 1

mapper.update:
UPDATE SMT_ISC_CARD_TASK
SET STATUS = 0,
	RUNNING_KEY = NULL,
	LEASE_TOKEN = NULL,
	OVER_TIME = #{currentTime},
	UPDATE_TIME = #{updateTime}
WHERE RUNNING_KEY = #{runningKey}
  AND STATUS = 3
  AND OVER_TIME <= #{currentTime}
  AND (CODE != 200 OR CODE IS NULL)
